.dg-rich-text b {
  font-weight: var(--dg-rich-text-highlight-weight);
  color: var(--dg-rich-text-highlight, var(--h-fg-brand-default))
}

.dg-rich-text .dg-rich-text__muted {
  color: var(--h-color-neutral-500)
}

.dg-rich-text .dg-rich-text__disabled {
  color: var(--h-fg-neutral-disabled)
}

.dg-rich-text h1 {
  display: inline
}

.dg-rich-text .header__overline-discount {
  color: var(--h-fg-brand-default);
  font-weight: 600
}

.dg-rich-text .header__heading-discount {
  color: var(--h-fg-brand-default)
}

.dg-rich-text .header__overline--brand-color {
  color: var(--h-color-primary-400)
}

.dg-rich-text .header__heading-h-color-warning-400 {
  color: var(--h-color-warning-400)
}

.dg-rich-text .header__offer-price {
  font-size: 20px
}

.dg-rich-text__inline-heading {
  font: inherit;
  letter-spacing: inherit;
  display: inline
}

.dg-rich-text__light-links a,
.dg-rich-text__light-links a:hover {
  color: var(--h-color-neutral-0)
}

.dg-rich-text__brand-link,
.dg-rich-text__brand-link:hover {
  color: var(--h-fg-brand-default)
}

.dg-rich-text__body-copy a,
.dg-rich-text__body-copy a:hover {
  color: unset;
  text-decoration: underline;
  display: inline
}

.dg-rich-text__body-copy li {
  margin-inline-start: 24px
}

.dg-rich-text__highlight {
  color: var(--dg-rich-text-highlight, var(--h-fg-brand-default))
}

.dg-rich-text__eyebrow {
  color: var(--h-fg-brand-default);
  margin-bottom: 16px;
  display: block
}

.dg-rich-text__label {
  background-color: var(--h-color-primary-a15);
  color: var(--h-fg-neutral-default);
  border-radius: 40px;
  padding: 4px 12px;
  display: inline-block
}

.dg-rich-text__eyebrow.dg-rich-text__label {
  width: fit-content;
  margin-inline: auto;
  display: block
}

.ak-agent-mark {
  -webkit-user-select: none;
  user-select: none;
  flex-shrink: 0;
  position: relative
}

.ak-agent-mark__canvas,
.ak-agent-mark__image {
  width: 100%;
  height: 100%;
  transition: opacity .4s ease-out;
  display: block;
  position: absolute;
  inset: 0
