.sales-float-btn {
  isolation: isolate;
  border-radius: var(--h-border-radius-full);
  cursor: pointer;
  width: 56px;
  height: 56px;
  box-shadow: 0 0 20px var(--h-color-primary-a25);
  background: 0 0;
  border: none;
  justify-content: center;
  align-items: center;
  transition: transform .2s;
  display: flex;
  position: relative
}

.sales-float-btn:before {
  content: "";
  z-index: 0;
  border-radius: var(--h-border-radius-full);
  background: conic-gradient(from 0deg, var(--h-color-primary-500), var(--h-color-meteorite-500), var(--h-color-blue-500), var(--h-color-primary-500));
  opacity: .85;
  filter: blur(8px);
  animation: 4s linear infinite sales-float-glow-spin-e0dc192f;
  position: absolute;
  inset: -2px
}

.sales-float-btn:after {
  content: "";
  z-index: 1;
  border-radius: var(--h-border-radius-full);
  background: var(--h-color-neutral-950);
  border: 1px solid var(--h-color-light-a15);
  position: absolute;
  inset: 2px
}

.sales-float-btn:hover {
  transform: scale(1.05)
}

.sales-float-btn:active {
  transform: scale(.95)
}

.sales-float-btn:focus-visible {
  outline: 2px solid var(--h-stroke-brand);
  outline-offset: 4px
}

.sales-float-btn__icon {
  z-index: 2;
  position: relative
}

@keyframes sales-float-glow-spin-e0dc192f {
  to {
    transform: rotate(1turn)
  }
}

.spin-enter-active,
.spin-leave-active {
  transition: opacity .15s, transform .15s
}

.spin-enter-from {
  opacity: 0;
  transform: rotate(90deg)scale(.7)
}

.spin-leave-to {
  opacity: 0;
  transform: rotate(-90deg)scale(.7)
}

.sales-csat-stars {
  align-items: center;
  gap: var(--h-spacing-3xs);
  padding: 0 var(--h-spacing-4xs);
  display: flex
}

.sales-csat-stars__star {
  transition: transform .12s;
  display: inline-flex
}

.sales-csat-stars__star:hover {
  transform: scale(1.08)
}

.sales-csat-stars__star-btn {
  padding: 0
}

@media (prefers-reduced-motion:reduce) {
  .sales-csat-stars__star {
    transition: none
  }
}

.sales-csat-notification {
  gap: var(--h-spacing-2xs);
  width: 100%;
  max-width: 320px;
  padding: var(--h-spacing-sm)
}

.sales-csat-notification__header {
  align-items: flex-start;
  gap: var(--h-spacing-2xs);
  display: flex
}

.sales-csat-notification__text {
  gap: var(--h-spacing-4xs);
  min-width: 0;
  padding: var(--h-spacing-3xs) var(--ak-block-inset) 0;
  flex-direction: column;
  flex: 1;
  display: flex
}

.sales-csat-notification-enter-active {
  transition: opacity .3s, transform .35s cubic-bezier(.16, 1, .3, 1)
}

.sales-csat-notification-leave-active,
.sales-slide-down-fade-enter-active,
.sales-slide-down-fade-leave-active,
.sales-slide-from-left-fade-enter-active,
.sales-slide-from-left-fade-leave-active,
.sales-slide-from-right-fade-enter-active,
.sales-slide-from-right-fade-leave-active,
.sales-slide-up-fade-enter-active,
.sales-slide-up-fade-leave-active {
  transition: opacity .2s, transform .2s
}

.sales-csat-notification-enter-from,
.sales-csat-notification-leave-to {
  opacity: 0;
  transform: translateY(12px)scale(.96)
}

.sales-slide-up-fade-enter-from,
.sales-slide-up-fade-leave-to {
  opacity: 0;
  transform: translateY(12px)
}

.sales-slide-down-fade-enter-from,
.sales-slide-down-fade-leave-to {
  opacity: 0;
  transform: translateY(-12px)
}

.sales-slide-from-right-fade-enter-from,
