  opacity: 0;
  transform: translate(12px)
}

.sales-slide-from-left-fade-enter-from,
.sales-slide-from-left-fade-leave-to {
  opacity: 0;
  transform: translate(-12px)
}

.sales-sidebar-slide-enter-active,
